using System;using System.IO;using System.Linq;using UnityEngine;
public static class InputPrepareReviewR18 {
 static void Send(CrabFlightGame g,int id,string method,string payload=""){g.ReceiveInputR23(JsonUtility.ToJson(new FlightInputR23{id=id,method=method,payload=payload}));}
 static void Drain(CrabFlightGame g){for(int k=0;k<10000&&g.State().phase=="preparing";k++)g.Tick(1f/60);if(g.State().phase=="preparing"||g.State().phase=="error")throw new Exception("Preparation failed");}
 public static void Run(){var dir=Path.GetFullPath("../../../../finish-r18-evidence/native-input01");Directory.CreateDirectory(dir);CrabFlightGame g=null;try{UnityEngine.Random.InitState(42043);g=BuildFlight.PrepareScene();g.Initialize();g.enabled=false;g.LoadFeelR27(File.ReadAllText("Assets/StreamingAssets/feel.json"));g.ReviewReplayAcceptedCalmR3(File.ReadAllText("../../../../accepted-input.json"));for(int k=0;k<18000&&!g.Finished;k++)g.Tick(1f/60);if(!g.Finished)throw new Exception("Reference incomplete");var previous=g.State().launchReceipt;Send(g,300,"RetryLaunch");if(g.State().phase!="preparing"||g.State().inputAcks.Any(x=>x.id==300))throw new Exception("Retry falsely acknowledged ready");Drain(g);var a=g.State();if(a.phase!="flight"||a.launchReceipt.source!="retry"||a.launchReceipt.phase!=previous.phase||a.launchReceipt.spin!=previous.spin||a.launchReceipt.power!=previous.power||!a.inputAcks.Any(x=>x.id==300&&x.accepted))throw new Exception("Retained retry input changed");Send(g,301,"Prepare");Send(g,302,"SetUpgradeLevel","3");Send(g,303,"Configure",previous.settingsJson);g.SetPaused("1");if(g.State().inputAcks.Any(x=>x.id>=301))throw new Exception("Queued input acknowledged before application");Drain(g);a=g.State();if(a.phase!="ready"||!a.paused||a.chargeStarted||a.chargeReady||a.launchReceipt!=null||new[]{301,302,303}.Any(id=>!a.inputAcks.Any(x=>x.id==id&&x.accepted)))throw new Exception("Prepare queue/pause/stale launch failed");g.SetPaused("0");File.WriteAllText(dir+"/state.json",JsonUtility.ToJson(g.State(),true));File.WriteAllText(dir+"/receipt.json","{\"retainedRetryAccepted\":true,\"prepareAckDeferred\":true,\"configureLevelAppliedInOrder\":true,\"pauseRetained\":true,\"staleChargeAndLaunchCleared\":true,\"diagnosticCompletedFlights\":1,\"diagnosticZeroStepRetryLaunches\":1}");File.WriteAllText(dir+"/work.json",g.ReviewPreparationR18());}finally{if(g)g.ShutdownReviewPhysics();}}
 public static void PausedRetry(){var dir=Path.GetFullPath("../../../../finish-r18-evidence/native-paused02");Directory.CreateDirectory(dir);CrabFlightGame g=null;try{UnityEngine.Random.InitState(42043);g=BuildFlight.PrepareScene();g.Initialize();g.enabled=false;g.LoadFeelR27(File.ReadAllText("Assets/StreamingAssets/feel.json"));g.ReviewReplayAcceptedCalmR3(File.ReadAllText("../../../../accepted-input.json"));for(int k=0;k<18000&&!g.Finished;k++)g.Tick(1f/60);if(!g.Finished)throw new Exception("Reference incomplete");int attempts=g.State().attempts;Send(g,400,"RetryLaunch");g.SetPaused("1");Drain(g);var s=g.State();var ack=s.inputAcks.Single(x=>x.id==400);if(ack.accepted||ack.reason!="paused-during-preparation"||s.phase!="ready"||!s.paused||s.attempts!=attempts||s.launchReceipt!=null||s.chargeReady||s.chargeStarted)throw new Exception("Paused retry falsely launched or reused old charge");g.SetPaused("0");File.WriteAllText(dir+"/state.json",JsonUtility.ToJson(g.State(),true));File.WriteAllText(dir+"/receipt.json","{\"pausedRetryRejectedWithReason\":true,\"attemptsUnchanged\":true,\"noOldChargeOrLaunch\":true,\"resumedReady\":true}");}finally{if(g)g.ShutdownReviewPhysics();}}

}
